oxy_webhelp_navlinks = {"aws_workloads-d39536e15549":{"topics":[{"title":"Introduction to AWS protection","shortdesc":"<p class=\"shortdesc\">Describes an overview of AWS protection, the key features, common protection\n                    terms, high-level architecture, and tag management for protecting AWS workloads\n                    with <span class=\"ph\">RSC<\/span>.<\/p>","href":"saas\/aws_protection_overview.html","menu":{"hasChildren":false},"tocID":"tocId-d39536e15565","next":"tocId-d39536e15565"},{"title":"AWS protection implementation workflow","shortdesc":"<p class=\"shortdesc\">The AWS protection implementation workflow involves a structured approach to secure         data management, starting with planning and preparation, followed by cloud account setup,         infrastructure configuration, setup verification, workload protection, continuous         management and optimization, and workload recovery.<\/p>","href":"saas\/aws_protect_implementation.html","attributes":{"data-id":"aws_protect_implementation"},"menu":{"hasChildren":false},"tocID":"aws_protect_implementation-d39536e15765","topics":[]},{"title":"Quick links for AWS workloads","shortdesc":"<p class=\"shortdesc\">Immediate access to important tasks and information, enabling quick setup, daily         operations, and critical recovery.<\/p>","href":"saas\/aws_quick_links.html","attributes":{"data-id":"aws_quick_links"},"menu":{"hasChildren":false},"tocID":"aws_quick_links-d39536e15776","topics":[]},{"title":"Plan your AWS protection","shortdesc":"<p class=\"shortdesc\">Before setting up an AWS cloud account in <span class=\"ph\">RSC<\/span>, it is necessary to         plan the user and access management for designated <span class=\"ph\">RSC<\/span> users. This planning         also involves reviewing the permissions that <span class=\"ph\">RSC<\/span> requires in your AWS         environment to protect your AWS workloads.<\/p>","href":"saas\/aws_planning_protection.html","attributes":{"data-id":"aws_planning_protection"},"menu":{"hasChildren":false},"tocID":"aws_planning_protection-d39536e15787","next":"aws_planning_protection-d39536e15787"},{"title":"Deploy <span class=\"ph\">RSC<\/span>-managed AWS protection","shortdesc":"<p class=\"shortdesc\">Plan, connect, and verify an AWS account that uses the <span class=\"ph\">RSC<\/span>-managed         deployment model, where <span class=\"ph\">RSC<\/span> provisions and operates the compute and storage         resources for you.<\/p>","href":"saas\/aws_deploy_rsc_managed.html","attributes":{"data-id":"aws_deploy_rsc_managed"},"menu":{"hasChildren":false},"tocID":"aws_deploy_rsc_managed-d39536e15949","next":"aws_deploy_rsc_managed-d39536e15949"},{"title":"Deploy self-managed AWS protection","shortdesc":"<p class=\"shortdesc\">Plan, connect, and verify an AWS account that uses the self-managed deployment model,         where you provision and manage compute and storage resources in your own AWS         account.<\/p>","href":"saas\/aws_deploy_self_managed.html","attributes":{"data-id":"aws_deploy_self_managed"},"menu":{"hasChildren":false},"tocID":"aws_deploy_self_managed-d39536e16186","next":"aws_deploy_self_managed-d39536e16186"},{"title":"Verifying your AWS account setup","shortdesc":"<p class=\"shortdesc\">Confirm that the AWS account is connected, that <span class=\"ph\">RSC<\/span> discovers your         workloads, and that the permissions are in place before you assign protection.<\/p>","href":"saas\/aws_verify_account_setup.html","attributes":{"data-id":"aws_verify_account_setup"},"menu":{"hasChildren":false},"tocID":"aws_verify_account_setup-d39536e17674","topics":[]},{"title":"Set up AWS workloads protection","shortdesc":"<p class=\"shortdesc\">You can set up SLA Domains to apply data protection policies, ensuring automatic and         hierarchical protection of AWS accounts and individual AWS workloads, with granular control         overriding higher-level assignments.<\/p>","href":"saas\/aws_workloads_protection_setup.html","attributes":{"data-id":"aws_workloads_protection_setup"},"menu":{"hasChildren":false},"tocID":"aws_workloads_protection_setup-d39536e17688","next":"aws_workloads_protection_setup-d39536e17688"},{"title":"Manage Amazon EC2 instances and EBS volumes","shortdesc":"<p class=\"shortdesc\">After you set up protection for Amazon EC2 instances and EBS volumes, <span class=\"ph\">RSC<\/span> takes automated snapshots of those instances and volumes based on the         configured policies in SLA Domains. You can also take on-demand snapshots, refresh AWS         accounts, and add AWS custom tags for better resource management.<\/p>","href":"saas\/aws_ec2_ebs_volume.html","attributes":{"data-id":"aws_ec2_ebs_volume"},"menu":{"hasChildren":false},"tocID":"aws_ec2_ebs_volume-d39536e18338","next":"aws_ec2_ebs_volume-d39536e18338"},{"title":"Manage Amazon RDS and Aurora databases","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> protects the data and resources of Amazon RDS and Amazon Aurora         databases.<\/p>","href":"saas\/aws_rds.html","attributes":{"data-id":"aws_rds"},"menu":{"hasChildren":false},"tocID":"aws_rds-d39536e18660","next":"aws_rds-d39536e18660"},{"title":"Manage Amazon S3","shortdesc":"<p class=\"shortdesc\">With <span class=\"ph\">RSC<\/span>, you can protect and recover your Amazon S3 buckets and         objects.<\/p>","href":"amazon_S3\/amazon_s3.html","attributes":{"data-id":"amazon_s3"},"menu":{"hasChildren":false},"tocID":"amazon_s3-d39536e18792","next":"amazon_s3-d39536e18792"},{"title":"Manage Amazon DynamoDB","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> secures Amazon DynamoDB tables with automated snapshots governed         by SLA Domain policies. You can gain insights from detailed snapshot data and optimize         resources using on-demand account refresh and AWS custom tags.<\/p>","href":"saas\/aws_dynamodb.html","attributes":{"data-id":"aws_dynamodb"},"menu":{"hasChildren":false},"tocID":"aws_dynamodb-d39536e18899","next":"aws_dynamodb-d39536e18899"},{"title":"Manage AWS Glue Iceberg Tables","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> protects Iceberg tables registered in your AWS Glue catalog with         automated snapshots configured in SLA Domain policies. You can view inventory details,         manage protection assignments, and recover Iceberg tables from the AWS Glue Iceberg Tables         inventory page.<\/p>","href":"aws\/aws_glue_tables.html","attributes":{"data-id":"aws_glue_tables"},"menu":{"hasChildren":false},"tocID":"aws_glue_tables-d39536e18976","next":"aws_glue_tables-d39536e18976"},{"title":"Manage AWS S3 Tables","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> protects Iceberg tables stored in your AWS S3 table buckets with         automated snapshots configured in your SLA Domain policies. You can view inventory details,         manage protection assignments, and recover Iceberg tables from the AWS S3 Tables inventory         page.<\/p>","href":"aws\/aws_s3_tables.html","attributes":{"data-id":"aws_s3_tables"},"menu":{"hasChildren":false},"tocID":"aws_s3_tables-d39536e19047","next":"aws_s3_tables-d39536e19047"},{"title":"Manage AWS cloud accounts","shortdesc":"<p class=\"shortdesc\">You can manage the AWS cloud accounts available in <span class=\"ph\">RSC<\/span>.<\/p>","href":"saas\/aws_manage_cld_acc.html","attributes":{"data-id":"aws_manage_cld_acc"},"menu":{"hasChildren":false},"tocID":"aws_manage_cld_acc-d39536e19118","next":"aws_manage_cld_acc-d39536e19118"},{"title":"Recover AWS workloads","shortdesc":"<p class=\"shortdesc\">After <span class=\"ph\">RSC<\/span> takes snapshots of your AWS workloads, you can recover the         required workloads.<\/p>","href":"saas\/aws_workload_recovery.html","attributes":{"data-id":"aws_workload_recovery"},"menu":{"hasChildren":false},"tocID":"aws_workload_recovery-d39536e19428","next":"aws_workload_recovery-d39536e19428"}]}};